CREATE TABLE IF NOT EXISTS department (department_id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS role (role_id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, access_profile TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS manager (manager_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL UNIQUE, department_id TEXT NOT NULL REFERENCES department(department_id), active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS employee (employee_id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, department_id TEXT NOT NULL REFERENCES department(department_id), role_id TEXT NOT NULL REFERENCES role(role_id), manager_id TEXT REFERENCES manager(manager_id), employment_type TEXT NOT NULL CHECK(employment_type IN ('permanent','contractor')), work_location TEXT NOT NULL CHECK(work_location IN ('remote','on_site')), status TEXT NOT NULL CHECK(status IN ('active','terminated')), hire_date DATE NOT NULL, start_date DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE manager DROP CONSTRAINT IF EXISTS manager_employee_id_fkey;
ALTER TABLE manager ADD CONSTRAINT manager_employee_id_fkey FOREIGN KEY(employee_id) REFERENCES employee(employee_id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE IF NOT EXISTS onboarding_case (onboarding_case_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL UNIQUE REFERENCES employee(employee_id), process_owner_employee_id TEXT REFERENCES employee(employee_id), status TEXT NOT NULL CHECK(status IN ('pending','in_progress','completed','cancelled')), start_date DATE NOT NULL, target_completion_date DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS task_template (task_template_id TEXT PRIMARY KEY, role_id TEXT NOT NULL REFERENCES role(role_id), work_location TEXT NOT NULL CHECK(work_location IN ('remote','on_site')), task_name TEXT NOT NULL, sla_days INTEGER NOT NULL CHECK(sla_days>=0), dependency_key TEXT NOT NULL DEFAULT '', required BOOLEAN NOT NULL DEFAULT true, UNIQUE(role_id,work_location,task_name));
CREATE TABLE IF NOT EXISTS task_instance (task_id TEXT PRIMARY KEY, onboarding_case_id TEXT NOT NULL REFERENCES onboarding_case(onboarding_case_id), employee_id TEXT NOT NULL REFERENCES employee(employee_id), task_template_id TEXT NOT NULL REFERENCES task_template(task_template_id), task_name TEXT NOT NULL, owner_employee_id TEXT REFERENCES employee(employee_id), status TEXT NOT NULL CHECK(status IN ('pending','in_progress','completed','cancelled')), due_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, depends_on JSONB NOT NULL DEFAULT '[]'::jsonb, issue_type TEXT);
CREATE TABLE IF NOT EXISTS asset (asset_id TEXT PRIMARY KEY, asset_type TEXT NOT NULL, serial_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('available','assigned','repair','retired')), assigned_employee_id TEXT REFERENCES employee(employee_id), assigned_at DATE, CHECK((status='assigned' AND assigned_employee_id IS NOT NULL) OR status<>'assigned'));
CREATE TABLE IF NOT EXISTS access_request (access_request_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employee(employee_id), system_name TEXT NOT NULL, requested_by_employee_id TEXT REFERENCES employee(employee_id), status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','active','revoked')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), approved_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, issue_type TEXT);
CREATE TABLE IF NOT EXISTS approval (approval_id TEXT PRIMARY KEY, access_request_id TEXT NOT NULL REFERENCES access_request(access_request_id), approver_employee_id TEXT NOT NULL REFERENCES employee(employee_id), decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), comments TEXT, decided_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_event (audit_event_id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, event_type TEXT NOT NULL, issue_type TEXT, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_employee_department ON employee(department_id); CREATE INDEX IF NOT EXISTS idx_task_status_due ON task_instance(status,due_at); CREATE INDEX IF NOT EXISTS idx_access_employee_status ON access_request(employee_id,status); CREATE INDEX IF NOT EXISTS idx_audit_issue ON audit_event(issue_type) WHERE issue_type IS NOT NULL;
CREATE TABLE IF NOT EXISTS offboarding_case (offboarding_case_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employee(employee_id), process_owner_employee_id TEXT REFERENCES employee(employee_id), status TEXT NOT NULL CHECK(status IN ('pending','in_progress','completed','cancelled')), termination_date DATE NOT NULL, access_revocation_required BOOLEAN NOT NULL DEFAULT true, asset_recovery_required BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_offboarding_status_date ON offboarding_case(status,termination_date);
ALTER TABLE task_instance ADD COLUMN IF NOT EXISTS offboarding_case_id TEXT REFERENCES offboarding_case(offboarding_case_id);
CREATE INDEX IF NOT EXISTS idx_task_offboarding_case ON task_instance(offboarding_case_id) WHERE offboarding_case_id IS NOT NULL;
